svg.script:
(() => {
  "use strict";

  const $ = id => document.getElementById(id);
  const el = {
    board: $("board"),
    legB: $("legBack"), legF: $("legFront"),
    armB: $("armBack"), armF: $("armFront"),
    torso: $("torso"),
    shoeB: $("shoeBack"), shoeF: $("shoeFront"),
    handB: $("handBack"), handF: $("handFront"),
    head: $("head"),
    badge: $("trickBadge"), label: $("trickLabel")
  };

  // Geometry: 180 px = 2.4 m. The flat bottom is 400 px long.
  const SCALE = 75;                 // pixels per metre
  const G = 9.81;                   // m/s²
  const R = 180;
  const ARC = Math.PI * R / 2;
  const FLAT = 400;
  const TOTAL = 2 * ARC + FLAT;
  const HEIGHT = R / SCALE;
  const LIP_SPEED = 5.0;            // m/s, about 18 km/h
  const BOTTOM_V2 =
    LIP_SPEED * LIP_SPEED + 2 * G * HEIGHT;
  const FLIGHT_TIME = 2 * LIP_SPEED / G;

  const clamp = (v, lo = 0, hi = 1) =>
    Math.max(lo, Math.min(hi, v));
  const mix = (a, b, t) => a + (b - a) * t;
  const smooth = (a, b, x) => {
    const t = clamp((x - a) / (b - a));
    return t * t * (3 - 2 * t);
  };
  const add = (a, b) => ({x: a.x + b.x, y: a.y + b.y});
  const mul = (a, k) => ({x: a.x * k, y: a.y * k});
  const mixP = (a, b, t) =>
    ({x: mix(a.x, b.x, t), y: mix(a.y, b.y, t)});
  const norm = a => {
    const d = Math.hypot(a.x, a.y) || 1;
    return {x: a.x / d, y: a.y / d};
  };
  const pt = p => `${p.x.toFixed(1)} ${p.y.toFixed(1)}`;
  const setD = (node, d) => node.setAttribute("d", d);

  // Position and tangent along the ramp, measured from the left lip.
  function surface(s) {
    s = clamp(s, 0, TOTAL);
    let x, y, phi;

    if (s < ARC) {
      phi = Math.PI - s / R;
      x = 300 + R * Math.cos(phi);
      y = 320 + R * Math.sin(phi);
    } else if (s < ARC + FLAT) {
      x = 300 + s - ARC;
      y = 500;
      phi = Math.PI / 2;
    } else {
      phi = Math.PI / 2 - (s - ARC - FLAT) / R;
      x = 700 + R * Math.cos(phi);
      y = 320 + R * Math.sin(phi);
    }

    return {
      x, y,
      tx: Math.sin(phi),
      ty: -Math.cos(phi),
      h: (500 - y) / SCALE
    };
  }

  function rampUp(p) {
    // Blend the surface normal with world-up so the skater does not
    // unrealistically lie horizontal on the vertical part of the wall.
    const nx = p.ty, ny = -p.tx;
    return norm({x: 0.55 * nx, y: 0.55 * ny - 0.85});
  }

  // Two-bone visual IK for knees and elbows.
  function ik(a, b, l1, l2, bend) {
    const dx = b.x - a.x, dy = b.y - a.y;
    const raw = Math.max(0.001, Math.hypot(dx, dy));
    const d = clamp(raw, Math.abs(l1 - l2) + 0.001,
                         l1 + l2 - 0.001);
    const ux = dx / raw, uy = dy / raw;
    const along = (l1 * l1 - l2 * l2 + d * d) / (2 * d);
    const out = Math.sqrt(Math.max(0, l1 * l1 - along * along));

    return {
      x: a.x + ux * along - uy * out * bend,
      y: a.y + uy * along + ux * out * bend
    };
  }

  function keyed(u, keys) {
    for (let i = 1; i < keys.length; i++) {
      if (u <= keys[i][0]) {
        const a = keys[i - 1], b = keys[i];
        return mix(a[1], b[1], smooth(a[0], b[0], u));
      }
    }
    return keys[keys.length - 1][1];
  }

  function draw(root, angle, up, crouch, face, grab, trick) {
    el.board.setAttribute(
      "transform",
      `translate(${root.x.toFixed(2)} ${root.y.toFixed(2)}) rotate(${angle.toFixed(2)})`
    );

    const r = angle * Math.PI / 180;
    const co = Math.cos(r), si = Math.sin(r);
    const axis = {x: co, y: si};
    const boardPoint = (x, y) => ({
      x: root.x + x * co - y * si,
      y: root.y + x * si + y * co
    });

    const footB = boardPoint(-14, -4);
    const footF = boardPoint(14, -4);
    const hip = add(root, mul(up, 62 - 26 * crouch));
    const side = {x: -up.y, y: up.x};
    const forward = mul(side, face);
    const down = mul(up, -1);
    const shoulder = add(
      add(hip, mul(up, 30 - 4 * crouch)),
      mul(forward, 1.5)
    );
    const head = add(shoulder, mul(up, 17));

    const kneeB = ik(hip, footB, 38, 42, -face);
    const kneeF = ik(hip, footF, 38, 42, -face);

    setD(el.legB, `M${pt(hip)} L${pt(kneeB)} L${pt(footB)}`);
    setD(el.legF, `M${pt(hip)} L${pt(kneeF)} L${pt(footF)}`);
    setD(el.torso, `M${pt(hip)} L${pt(shoulder)}`);

    const shoe = foot =>
      `M${pt(add(foot, mul(axis, -4)))} L${pt(add(foot, mul(axis, 8)))}`;
    setD(el.shoeB, shoe(footB));
    setD(el.shoeF, shoe(footF));

    // Balance arms normally; one hand moves to the deck during a grab.
    let handF = add(
      add(shoulder, mul(forward, 34)),
      mul(down, 7 + 4 * crouch)
    );
    let handB = add(
      add(shoulder, mul(forward, -29)),
      mul(down, 15 + 3 * crouch)
    );

    const grabPoint = boardPoint(trick === 0 ? 12 : -12, -3);
    if (trick === 0) {
      handF = mixP(handF, grabPoint, grab);
      handB = add(handB, mul(up, 12 * grab));
    } else {
      handB = mixP(handB, grabPoint, grab);
      handF = add(handF, mul(up, 12 * grab));
    }

    const elbowF = ik(shoulder, handF, 35, 37, face);
    const elbowB = ik(shoulder, handB, 35, 37, -face);
    setD(el.armF, `M${pt(shoulder)} L${pt(elbowF)} L${pt(handF)}`);
    setD(el.armB, `M${pt(shoulder)} L${pt(elbowB)} L${pt(handB)}`);

    for (const [node, p] of [[el.handF, handF], [el.handB, handB]]) {
      node.setAttribute("cx", p.x);
      node.setAttribute("cy", p.y);
    }

    const headRotation =
      Math.atan2(up.y, up.x) * 180 / Math.PI + 90;
    el.head.setAttribute(
      "transform",
      `translate(${head.x.toFixed(2)} ${head.y.toFixed(2)}) rotate(${headRotation.toFixed(2)})`
    );
  }

  let mode = "ride";
  let direction = 1;       // +1: left to right, -1: right to left
  let distance = 0;
  let launchDirection = 1;
  let airTime = 0;
  let trick = 0;

  function step(dt) {
    if (mode === "ride") {
      const p = surface(distance);

      // Energy conservation: v² = v_bottom² - 2gh.
      // Thus the skater is fastest at the bottom and reaches each lip
      // at LIP_SPEED. This idealized model neglects friction and drag.
      const speed = Math.sqrt(
        Math.max(0.01, BOTTOM_V2 - 2 * G * p.h)
      );
      distance += direction * speed * SCALE * dt;

      if ((direction > 0 && distance >= TOTAL) ||
          (direction < 0 && distance <= 0)) {
        distance = direction > 0 ? TOTAL : 0;
        launchDirection = direction;
        trick = direction > 0 ? 0 : 1;
        airTime = 0;
        mode = "air";
      }
    } else {
      airTime += dt;

      if (airTime >= FLIGHT_TIME) {
        // Take-off and landing speeds are equal because landing occurs
        // at the same height. Reverse direction for the next transition.
        airTime = FLIGHT_TIME;
        mode = "ride";
        direction = -launchDirection;
        distance = launchDirection > 0 ? TOTAL : 0;
      }
    }
  }

  function render() {
    let root, angle, up, crouch, face;
    let grab = 0;

    if (mode === "ride") {
      const p = surface(distance);
      root = {
        x: p.x + 8 * p.ty,
        y: p.y - 8 * p.tx
      };
      angle = Math.atan2(
        direction * p.ty,
        direction * p.tx
      ) * 180 / Math.PI;

      up = rampUp(p);

      // Extended near the bottom, compressed near the lips. Additional
      // flex just after landing suggests impact absorption and pumping.
      crouch = 0.12 + 0.48 * clamp(p.h / HEIGHT);
      const travelled = direction > 0 ? distance : TOTAL - distance;
      crouch += 0.20 *
        (1 - clamp(travelled / (0.65 * SCALE)));

      face = direction;
      el.badge.setAttribute("opacity", "0");
    } else {
      const u = clamp(airTime / FLIGHT_TIME);
      const lip = surface(launchDirection > 0 ? TOTAL : 0);
      const x0 = lip.x + 8 * lip.ty;
      const y0 = lip.y - 8 * lip.tx;

      // Exact vertical projectile motion. There is no horizontal velocity
      // at a vertical lip, so x remains constant until re-entry.
      root = {
        x: x0,
        y: y0 - SCALE * LIP_SPEED * airTime
                + 0.5 * SCALE * G * airTime * airTime
      };

      // Level the board after take-off, then align it with the transition
      // before landing. The small middle tilt differs on each side.
      if (u < 0.22) {
        angle = -90 + 90 * smooth(0, 0.22, u);
      } else if (u > 0.78) {
        angle = 90 * smooth(0.78, 1, u);
      } else {
        const q = (u - 0.22) / 0.56;
        angle = launchDirection * 10 * Math.sin(Math.PI * q);
      }

      const worldUp = {x: 0, y: -1};
      const lipUp = rampUp(lip);
      if (u < 0.18) {
        up = norm(mixP(lipUp, worldUp, smooth(0, 0.18, u)));
      } else if (u > 0.82) {
        up = norm(mixP(worldUp, lipUp, smooth(0.82, 1, u)));
      } else {
        up = worldUp;
      }

      // Extend after launch, tuck for the grab, and prepare a bent-leg
      // landing. These poses do not alter the ballistic trajectory.
      crouch = keyed(u, [
        [0,    0.60],
        [0.18, 0.28],
        [0.43, 0.88],
        [0.62, 0.88],
        [1,    0.80]
      ]);

      // Smoothly reverse the visual stance for re-entry.
      face = launchDirection *
        Math.cos(Math.PI * smooth(0.26, 0.74, u));

      grab = smooth(0.24, 0.40, u) *
             (1 - smooth(0.60, 0.78, u));

      el.label.textContent =
        trick === 0 ? "INDY GRAB" : "MUTE GRAB";
      el.badge.setAttribute(
        "opacity",
        (smooth(0.08, 0.20, u) *
         (1 - smooth(0.82, 0.96, u))).toFixed(3)
      );
    }

    draw(root, angle, up, crouch, face, grab, trick);
  }

  let last = 0;
  function frame(now) {
    const dt = Math.min(0.033, Math.max(0, (now - last) / 1000));
    last = now;
    step(dt);
    render();
    requestAnimationFrame(frame);
  }

  render();

  // Respect the viewer's reduced-motion preference.
  if (!(window.matchMedia &&
        window.matchMedia("(prefers-reduced-motion: reduce)").matches)) {
    last = performance.now();
    requestAnimationFrame(frame);
  }
})();
